# Compiles compute shaders from an HLSL file whose #include "..." directives are searched in
# the given directories (flattened first, so fxc needs no include paths), and writes their
# bytecode into a C++ header as byte arrays.
# usage: embed_hlsl.py <input.hlsl> <output.h> <entry>[,<entry>...] <include dir>...
# Needs fxc on PATH (the Windows SDK; tools/vcenv.cmd sets it up).
import os
import re
import subprocess
import sys
import tempfile

src, out, entries = sys.argv[1], sys.argv[2], sys.argv[3].split(',')
dirs = [os.path.dirname(os.path.abspath(src))] + sys.argv[4:]
seen = set()


def flatten(path):
    text = []
    for line in open(path, encoding='utf-8', errors='replace'):
        m = re.match(r'\s*#\s*include\s+"([^"]+)"', line)
        if not m:
            text.append(line)
            continue
        found = None
        for d in [os.path.dirname(path)] + dirs:
            candidate = os.path.join(d, m.group(1))
            if os.path.exists(candidate):
                found = os.path.abspath(candidate)
                break
        if not found:
            # Inside a branch for another language (ffx_core.h includes its GLSL and CPU
            # variants conditionally): if it were needed, compiling would say so.
            text.append('// embed_hlsl: not found: ' + line)
            continue
        if found in seen:  # the FidelityFX headers have include guards; once is enough
            continue
        seen.add(found)
        text.append(flatten(found))
    return ''.join(text)


with tempfile.TemporaryDirectory() as tmp:
    flat = os.path.join(tmp, 'flat.hlsl')
    with open(flat, 'w', encoding='utf-8') as f:
        f.write(flatten(src))
    blobs = {}
    for entry in entries:
        cso = os.path.join(tmp, entry + '.cso')
        r = subprocess.run(['fxc', '/nologo', '/O3', '/T', 'cs_5_1', '/E', entry, '/Fo', cso, flat], capture_output=True, text=True)
        if r.returncode != 0:
            sys.exit('embed_hlsl: fxc failed for %s:\n%s%s' % (entry, r.stdout, r.stderr))
        blobs[entry] = open(cso, 'rb').read()

os.makedirs(os.path.dirname(os.path.abspath(out)), exist_ok=True)
with open(out, 'w', encoding='utf-8', newline='\n') as f:
    f.write('// Generated by tools/embed_hlsl.py from %s: do not edit.\n#pragma once\n' % os.path.basename(src))
    for entry, data in blobs.items():
        f.write('static const unsigned char k%s[] = {\n' % entry)
        for i in range(0, len(data), 24):
            f.write(','.join(str(b) for b in data[i:i + 24]) + ',\n')
        f.write('};\n')
print('embedded %s: %s' % (out, ', '.join('%s %d bytes' % (e, len(b)) for e, b in blobs.items())))
